3	.no-backdrop {
4	  width: 100%;
5	  height: 100vh;
6	  background-color: var(--backdrop-bg);
7	  -webkit-backdrop-filter: blur(var(--backdrop-blur));
8	  backdrop-filter: blur(var(--backdrop-blur));
9	  position: fixed;
10	  top: 0;
11	  left: 0;
12	  z-index: var(--z-index-backdrop);
13	  opacity: 0;
14	  visibility: hidden;
15	  will-change: opacity;
16	  transition: var(--backdrop-duration) var(--backdrop-delay) var(--backdrop-ease);
17	  transition-property: opacity, visibility;
18	
19	  &[aria-hidden="false"],
20	  &.is-open {
21	    opacity: 1;
22	    visibility: visible;
23	  }
24	}
