212	  --corner-btn-hover-color: var(--corner-btn-color);
213	  --corner-btn-hover-border: var(--clr-border-default);
214	  --corner-btn-hover-bg: color-mix(
215	    in srgb,
216	    var(--clr-border-weak) 12%,
217	    transparent
218	  );
219	  --corner-btn-hover-shadow: var(--corner-btn-shadow);
220	  --corner-btn-hover-corner: var(--clr-text-desc);
