223	  align-items: center;
224	  justify-content: center;
225	  padding: fluid(8, 12) fluid(14, 18);
226	  border: 1px solid var(--corner-btn-border);
227	  background: var(--corner-btn-bg);
228	  box-shadow: var(--corner-btn-shadow);
229	  color: var(--corner-btn-color);
230	  font-family: var(--family-ui);
231	  cursor: pointer;
232	  appearance: none;
233	  pointer-events: auto;
234	  transition:
235	    border-color var(--transition-default),
236	    background var(--transition-default),
237	    box-shadow var(--transition-default),
238	    color var(--transition-default);
239	
240	  &__text {
241	    display: inline;
242	  }
243	
244	  &__icon {
245	    display: inline-flex;
246	    align-items: center;
247	    margin-left: fluid(8, 12);
