263	    margin-right: 0;
264	  }
265	
266	  &.no-corner-btn--panel {
267	    --corner-panel-padding: fluid(20, 28);
268	    --corner-panel-border: var(--clr-border-weak);
269	    --corner-panel-background: transparent;
270	    --corner-panel-backdrop-filter: none;
271	    --corner-panel-corner: var(--clr-border-strong);
272	    --corner-panel-border-hover: var(--clr-border-default);
273	    --corner-panel-background-hover: color-mix(
274	      in srgb,
275	      var(--clr-border-weak) 12%,
276	      transparent
277	    );
278	    --corner-panel-hover-offset-y: 0px;
279	    --corner-panel-corner-hover: var(--clr-text-desc);
280	    --corner-btn-border: var(--corner-panel-border);
281	    --corner-btn-bg: var(--corner-panel-background);
282	    --corner-btn-corner: var(--corner-panel-corner);
283	    --corner-btn-hover-border: var(--corner-panel-border-hover);
284	    --corner-btn-hover-bg: var(--corner-panel-background-hover);
285	    --corner-btn-hover-corner: var(--corner-panel-corner-hover);
286	    display: flex;
287	    width: 100%;
288	    min-height: 100%;
289	    align-items: stretch;
290	    justify-content: flex-start;
291	    padding: var(--corner-panel-padding);
292	    cursor: default;
293	    text-align: left;
294	    transition:
295	      border-color var(--transition-default),
296	      background var(--transition-default),
297	      box-shadow var(--transition-default),
298	      color var(--transition-default),
299	      transform var(--transition-default);
300	    backdrop-filter: var(--corner-panel-backdrop-filter);
301	    -webkit-backdrop-filter: var(--corner-panel-backdrop-filter);
302	  }
303	
304	  &--highlight {
305	    --corner-btn-color: var(--clr-text-title);
306	    --corner-btn-border: color-mix(
307	      in srgb,
308	      var(--clr-text-title) 48%,
309	      transparent
310	    );
311	    --corner-btn-bg:
312	      linear-gradient(
313	          180deg,
314	          color-mix(in srgb, var(--clr-text-title) 16%, transparent),
315	          color-mix(in srgb, var(--clr-text-title) 8%, transparent)
316	        )
317	        0 0 / 100% 100% no-repeat,
318	      linear-gradient(
319	          90deg,
320	          transparent 0%,
321	          color-mix(in srgb, var(--clr-text-title) 22%, transparent) 48%,
322	          transparent 100%
323	        ) -140%
324	        0 / 60% 100% no-repeat;
325	    --corner-btn-shadow:
326	      inset 0 1px 0 color-mix(in srgb, var(--clr-text-title) 18%, transparent),
327	      0 0 0 1px color-mix(in srgb, var(--clr-text-title) 12%, transparent),
328	      0 0 fluid(20, 36)
329	        color-mix(in srgb, var(--clr-text-title) 22%, transparent);
330	    --corner-btn-corner: color-mix(
331	      in srgb,
332	      var(--clr-text-title) 72%,
333	      var(--clr-border-strong)
334	    );
335	    --corner-btn-hover-border: color-mix(
336	      in srgb,
337	      var(--clr-text-title) 68%,
338	      transparent
339	    );
340	    --corner-btn-hover-bg:
341	      linear-gradient(
342	          180deg,
343	          color-mix(in srgb, var(--clr-text-title) 22%, transparent),
344	          color-mix(in srgb, var(--clr-text-title) 12%, transparent)
345	        )
346	        0 0 / 100% 100% no-repeat,
347	      linear-gradient(
348	          90deg,
349	          transparent 0%,
350	          color-mix(in srgb, var(--clr-text-title) 28%, transparent) 48%,
351	          transparent 100%
352	        ) -140%
353	        0 / 60% 100% no-repeat;
354	    --corner-btn-hover-shadow:
355	      inset 0 1px 0 color-mix(in srgb, var(--clr-text-title) 24%, transparent),
356	      0 0 0 1px color-mix(in srgb, var(--clr-text-title) 18%, transparent),
357	      0 0 fluid(28, 48)
358	        color-mix(in srgb, var(--clr-text-title) 32%, transparent);
359	    --corner-btn-hover-corner: var(--clr-text-title);
